/* Photon by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
.ip-hero { max-width:none; padding:0; background:linear-gradient(45deg,#326f67,#324b97); }
.ip-hero .ip-header { padding:64px 32px; color:#ffffff; --pager-muted:#ffffff; }
.ip-title { font-weight:var(--pager-title-font-weight); letter-spacing:-.025em; }
.ip-hero .ip-navigation { background:#ffffff; color:#555555; padding:20px; margin:0; }
.ip-hero .ip-banner { max-width:1200px; height:280px; margin:0 auto; }
.ip-block::before { display:none; }
.ip-block .block-heading::after { content:''; display:block; width:100px; height:1px; background:var(--pager-border); margin-top:20px; }
@media(max-width:760px) { .ip-hero .ip-header { padding:48px 24px; } .ip-hero .ip-banner { height:220px; } }

.ip-description { opacity:1; }

.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
